package io.github.diodeme.ji.host.web;

import io.github.diodeme.ji.agent.AgentEvent;
import io.github.diodeme.ji.ai.Content;
import io.github.diodeme.ji.ai.Message;
import java.util.LinkedHashMap;
import java.util.Map;

/** Shared transient Agent event projection for REST and HCP clients. */
final class AgentEventPayload {
    private AgentEventPayload() {}

    static Map<String, Object> value(AgentEvent event) {
        var payload = new LinkedHashMap<String, Object>();
        payload.put("type", type(event));
        payload.put("runId", event.runId());
        payload.put("occurredAt", event.occurredAt().toString());
        if (event instanceof AgentEvent.MessageAdded added) {
            payload.put("message", message(added.message()));
        } else if (event instanceof AgentEvent.TextStreamed streamed) {
            payload.putAll(Map.of(
                    "messageId", streamed.messageId(),
                    "text", streamed.accumulatedText()));
        } else if (event instanceof AgentEvent.ToolChanged tool) {
            payload.putAll(Map.of(
                    "toolCallId", tool.toolCallId(),
                    "toolName", tool.toolName(),
                    "status", tool.status().name().toLowerCase(java.util.Locale.ROOT),
                    "arguments", tool.arguments(),
                    "result", tool.result()));
        } else if (event instanceof AgentEvent.PermissionChanged permission) {
            payload.putAll(Map.of(
                    "permissionId", permission.request().permissionId(),
                    "toolName", permission.request().toolName(),
                    "arguments", permission.request().arguments(),
                    "revision", permission.request().revision(),
                    "status", permission.status().name().toLowerCase(java.util.Locale.ROOT)));
        } else if (event instanceof AgentEvent.UsageChanged usage) {
            payload.put("usage", Map.of(
                    "inputTokens", usage.usage().inputTokens(),
                    "outputTokens", usage.usage().outputTokens(),
                    "cacheReadTokens", usage.usage().cacheReadTokens(),
                    "cacheWriteTokens", usage.usage().cacheWriteTokens(),
                    "costMicros", usage.usage().costMicros()));
        } else if (event instanceof AgentEvent.RunFinished finished) {
            payload.put("outcome", finished.outcome().name().toLowerCase(java.util.Locale.ROOT));
        } else if (event instanceof AgentEvent.RunFailed failed) {
            var error = new LinkedHashMap<String, Object>();
            error.put("code", failed.error().code().code());
            error.put("parameters", failed.error().parameters());
            failed.error().traceId().ifPresent(value -> error.put("traceId", value));
            failed.error().retryAfter().ifPresent(value -> error.put("retryAfterMillis", value.toMillis()));
            if (failed.error().currentRevision().isPresent()) {
                error.put("currentRevision", failed.error().currentRevision().getAsLong());
            }
            payload.put("error", Map.copyOf(error));
        }
        return Map.copyOf(payload);
    }

    private static Map<String, Object> message(Message message) {
        var value = new LinkedHashMap<String, Object>();
        value.put("id", message.id());
        value.put("role", message.role().name().toLowerCase(java.util.Locale.ROOT));
        value.put("text", message.text());
        message.toolCallId().ifPresent(id -> value.put("toolCallId", id));
        value.put("toolCalls", message.content().stream()
                .filter(Content.ToolCall.class::isInstance)
                .map(Content.ToolCall.class::cast)
                .map(call -> Map.of("id", call.id(), "name", call.name(), "arguments", call.arguments()))
                .toList());
        return Map.copyOf(value);
    }

    private static String type(AgentEvent event) {
        String name = event.getClass().getSimpleName();
        return name.replaceAll("([a-z])([A-Z])", "$1_$2").toLowerCase(java.util.Locale.ROOT);
    }
}
